#!/bin/sh
# Run through cargo-slot.sh. Every generated byte stays outside the checkout.
set -eu
: "${CARGO_TARGET_DIR:?use cargo-slot.sh}"
: "${CHARIOX_WORKER_DRILL_DIR:?set an external evidence directory}"
mkdir -p "$CHARIOX_WORKER_DRILL_DIR"
cargo build --manifest-path packages/app-wasm-worker/tests/guest/Cargo.toml --target wasm32-unknown-unknown --release
export CHARIOX_WORKER_DRILL_CORE="$CHARIOX_WORKER_DRILL_DIR/install.core.wasm"
trap 'rm -f "$CHARIOX_WORKER_DRILL_CORE"' EXIT
cp "$CARGO_TARGET_DIR/wasm32-unknown-unknown/release/chariox_app_worker_drill.wasm" "$CHARIOX_WORKER_DRILL_CORE"
cargo run -p chariox-app-wasm-worker --example package-drill -- "$CHARIOX_WORKER_DRILL_DIR/package"
cargo test -p chariox-app-wasm-worker --test installed -- --ignored --nocapture --test-threads=1
